    dict(key='30-class-5', kind='code', title='Gate — an exception covers a high advisory, until its day',
         body='// Gate: the deployment gate, with exceptions that end\nboolean covered = f.severity().equals("High")\n        && waivers.stream().anyMatch(w -> covers(w, f, today));\n...\nreturn (w.id().equals(f.id()) || w.id().equals(f.alias())) && w.endsOnDay() >= today;',
         narration="Only a high advisory can be covered, never a critical one. [[slnc 300]] And only while the exception's end day has not passed."),
